import React, { useEffect, useRef, useState } from 'react';
import { toast } from 'react-toastify';
import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiBookOpen,
  FiLayers,
  FiUploadCloud,
  FiX,
  FiCheckCircle,
  FiXCircle,
} from 'react-icons/fi';

import api, {
  getApiErrorMessage,
} from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const AdminCourses = () => {
  // =====================================================
  // TABS
  // =====================================================
  const [activeTab, setActiveTab] = useState('courses');

  // =====================================================
  // DATA
  // =====================================================
  const [courses, setCourses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  // =====================================================
  // COURSE STATE
  // =====================================================
  const [courseModalOpen, setCourseModalOpen] = useState(false);
  const [editingCourse, setEditingCourse] = useState(null);
  const [courseSubmitting, setCourseSubmitting] = useState(false);

  const [courseFormData, setCourseFormData] = useState({
    title: '',
    slug: '',
    description: '',
    category_id: '',
    duration: '',
    level: '',
    price: '',
    is_active: true,
    is_featured: false,
    order: 0,
  });

  const [courseImageFile, setCourseImageFile] = useState(null);
  const [courseImagePreview, setCourseImagePreview] = useState('');

  const courseFileRef = useRef(null);

  // =====================================================
  // CATEGORY STATE
  // =====================================================
  const [categoryModalOpen, setCategoryModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [categorySubmitting, setCategorySubmitting] = useState(false);

  const [categoryFormData, setCategoryFormData] = useState({
    name: '',
    slug: '',
    description: '',
    is_active: true,
    order: 0,
  });

  // =====================================================
  // LOAD DATA
  // =====================================================
  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);

      const [coursesRes, categoriesRes] = await Promise.all([
        api.get('/api/courses/'),
        api.get('/api/courses/categories'),
      ]);

      setCourses(
        Array.isArray(coursesRes.data)
          ? coursesRes.data
          : coursesRes.data?.items || []
      );

      setCategories(
        Array.isArray(categoriesRes.data)
          ? categoriesRes.data
          : categoriesRes.data?.items || []
      );
    } catch (error) {
      console.error('Fetch courses error:', error);
      toast.error(
        getApiErrorMessage(
          error,
          'Failed to load courses and categories'
        )
      );
    } finally {
      setLoading(false);
    }
  };

  // =====================================================
  // CREATE SLUG
  // =====================================================
  const createSlug = (value = '') => {
    return value
      .toLowerCase()
      .trim()
      .replace(/[^\w\s-]/g, '')
      .replace(/\s+/g, '-')
      .replace(/-+/g, '-');
  };

  // =====================================================
  // IMAGE URL HELPER
  // =====================================================
  const getImageUrl = (image) => {
    if (!image) return '';

    if (
      image.startsWith('http://') ||
      image.startsWith('https://') ||
      image.startsWith('blob:')
    ) {
      return image;
    }

    const baseURL =
      process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000';

    return `${baseURL}${image.startsWith('/') ? '' : '/'}${image}`;
  };

  // =====================================================
  // CATEGORY NAME
  // =====================================================
  const getCategoryName = (course) => {
    if (course.category?.name) {
      return course.category.name;
    }

    const category = categories.find(
      (item) =>
        String(item.id) === String(course.category_id)
    );

    return category?.name || 'No Category';
  };

  // =====================================================
  // RESET COURSE
  // =====================================================
  const resetCourseForm = () => {
    setEditingCourse(null);

    setCourseFormData({
      title: '',
      slug: '',
      description: '',
      category_id: '',
      duration: '',
      level: '',
      price: '',
      is_active: true,
      is_featured: false,
      order: 0,
    });

    setCourseImageFile(null);
    setCourseImagePreview('');

    if (courseFileRef.current) {
      courseFileRef.current.value = '';
    }
  };

  // =====================================================
  // OPEN ADD COURSE
  // =====================================================
  const handleAddCourse = () => {
    resetCourseForm();
    setCourseModalOpen(true);
  };

  // =====================================================
  // CLOSE COURSE
  // =====================================================
  const closeCourseModal = () => {
    setCourseModalOpen(false);
    resetCourseForm();
  };

  // =====================================================
  // COURSE IMAGE CHANGE
  // =====================================================
  const handleCourseImageChange = (e) => {
    const file = e.target.files?.[0];

    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Please select an image file');
      return;
    }

    const maxSize = 5 * 1024 * 1024;

    if (file.size > maxSize) {
      toast.error('Image must be less than 5MB');
      return;
    }

    setCourseImageFile(file);

    const previewURL = URL.createObjectURL(file);
    setCourseImagePreview(previewURL);
  };

  // =====================================================
  // REMOVE COURSE IMAGE
  // =====================================================
  const removeCourseImage = () => {
    setCourseImageFile(null);
    setCourseImagePreview('');

    if (courseFileRef.current) {
      courseFileRef.current.value = '';
    }
  };

  // =====================================================
  // EDIT COURSE
  // =====================================================
  const handleEditCourse = (course) => {
    setEditingCourse(course);

    setCourseFormData({
      title: course.title || '',
      slug: course.slug || '',
      description: course.description || '',
      category_id: course.category_id
        ? String(course.category_id)
        : '',
      duration: course.duration || '',
      level: course.level || '',
      price: course.price ?? '',
      is_active: course.is_active ?? true,
      is_featured: course.is_featured ?? false,
      order: course.order || 0,
    });

    setCourseImageFile(null);

    setCourseImagePreview(
      getImageUrl(
        course.image_url ||
          course.image ||
          course.thumbnail ||
          ''
      )
    );

    setCourseModalOpen(true);
  };

  // =====================================================
  // SUBMIT COURSE
  // =====================================================
  const handleCourseSubmit = async (e) => {
    e.preventDefault();

    try {
      setCourseSubmitting(true);

      const payload = new FormData();

      payload.append('title', courseFormData.title);
      payload.append('slug', courseFormData.slug);
      payload.append(
        'description',
        courseFormData.description || ''
      );

      if (courseFormData.category_id) {
        payload.append(
          'category_id',
          courseFormData.category_id
        );
      }

      payload.append(
        'duration',
        courseFormData.duration || ''
      );

      payload.append(
        'level',
        courseFormData.level || ''
      );

      if (
        courseFormData.price !== '' &&
        courseFormData.price !== null
      ) {
        payload.append(
          'price',
          String(courseFormData.price)
        );
      }

      payload.append(
        'is_active',
        String(courseFormData.is_active)
      );

      payload.append(
        'is_featured',
        String(courseFormData.is_featured)
      );

      payload.append(
        'order',
        String(courseFormData.order || 0)
      );

      if (courseImageFile) {
        payload.append('image_file', courseImageFile);
      }

      if (editingCourse) {
        await api.put(
          `/api/courses/${editingCourse.id}`,
          payload,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          }
        );

        toast.success('Course updated successfully');
      } else {
        await api.post('/api/courses/', payload, {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        });

        toast.success('Course created successfully');
      }

      closeCourseModal();
      await fetchData();
    } catch (error) {
      console.error('Save course error:', error);

      toast.error(
        getApiErrorMessage(
          error,
          'Failed to save course'
        )
      );
    } finally {
      setCourseSubmitting(false);
    }
  };

  // =====================================================
  // DELETE COURSE
  // =====================================================
  const handleDeleteCourse = async (id) => {
    const confirmed = window.confirm(
      'Are you sure you want to delete this course?'
    );

    if (!confirmed) return;

    try {
      await api.delete(`/api/courses/${id}`);

      toast.success('Course deleted successfully');

      await fetchData();
    } catch (error) {
      console.error('Delete course error:', error);

      toast.error(
        getApiErrorMessage(
          error,
          'Failed to delete course'
        )
      );
    }
  };

  // =====================================================
  // RESET CATEGORY
  // =====================================================
  const resetCategoryForm = () => {
    setEditingCategory(null);

    setCategoryFormData({
      name: '',
      slug: '',
      description: '',
      is_active: true,
      order: 0,
    });
  };

  // =====================================================
  // ADD CATEGORY
  // =====================================================
  const handleAddCategory = () => {
    resetCategoryForm();
    setCategoryModalOpen(true);
  };

  // =====================================================
  // CLOSE CATEGORY
  // =====================================================
  const closeCategoryModal = () => {
    setCategoryModalOpen(false);
    resetCategoryForm();
  };

  // =====================================================
  // EDIT CATEGORY
  // =====================================================
  const handleEditCategory = (category) => {
    setEditingCategory(category);

    setCategoryFormData({
      name: category.name || '',
      slug: category.slug || '',
      description: category.description || '',
      is_active: category.is_active ?? true,
      order: category.order || 0,
    });

    setCategoryModalOpen(true);
  };

  // =====================================================
  // SUBMIT CATEGORY
  // =====================================================
  const handleCategorySubmit = async (e) => {
    e.preventDefault();

    try {
      setCategorySubmitting(true);

      const payload = new FormData();

      payload.append(
        'name',
        categoryFormData.name
      );

      payload.append(
        'slug',
        categoryFormData.slug
      );

      payload.append(
        'description',
        categoryFormData.description || ''
      );

      payload.append(
        'is_active',
        String(categoryFormData.is_active)
      );

      payload.append(
        'order',
        String(categoryFormData.order || 0)
      );

      if (editingCategory) {
        await api.put(
          `/api/courses/categories/${editingCategory.id}`,
          payload,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          }
        );

        toast.success('Category updated successfully');
      } else {
        await api.post(
          '/api/courses/categories',
          payload,
          {
            headers: {
              'Content-Type': 'multipart/form-data',
            },
          }
        );

        toast.success('Category created successfully');
      }

      closeCategoryModal();
      await fetchData();
    } catch (error) {
      console.error('Save category error:', error);

      toast.error(
        getApiErrorMessage(
          error,
          'Failed to save category'
        )
      );
    } finally {
      setCategorySubmitting(false);
    }
  };

  // =====================================================
  // DELETE CATEGORY
  // =====================================================
  const handleDeleteCategory = async (id) => {
    const confirmed = window.confirm(
      'Are you sure you want to delete this category?'
    );

    if (!confirmed) return;

    try {
      await api.delete(
        `/api/courses/categories/${id}`
      );

      toast.success('Category deleted successfully');

      await fetchData();
    } catch (error) {
      console.error('Delete category error:', error);

      toast.error(
        getApiErrorMessage(
          error,
          'Failed to delete category'
        )
      );
    }
  };

  // =====================================================
  // COURSE COLUMNS
  // =====================================================
  const courseColumns = [
    {
      key: 'image',
      label: 'Image',

      render: (_, row) => {
        const image =
          row.image_url ||
          row.image ||
          row.thumbnail ||
          '';

        return image ? (
          <img
            src={getImageUrl(image)}
            alt={row.title || 'Course'}
            className="w-16 h-12 object-cover rounded-lg border border-blue-200"
            onError={(e) => {
              e.currentTarget.style.display = 'none';
            }}
          />
        ) : (
          <div className="w-16 h-12 rounded-lg bg-blue-50 flex items-center justify-center text-blue-900">
            <FiBookOpen size={20} />
          </div>
        );
      },
    },

    {
      key: 'title',
      label: 'Course',

      render: (val, row) => (
        <div>
          <p className="text-sm font-bold text-blue-900">
            {val || 'Untitled'}
          </p>

          {row.description && (
            <p className="text-xs text-blue-400 mt-1 max-w-[240px] truncate">
              {row.description}
            </p>
          )}
        </div>
      ),
    },

    {
      key: 'category_id',
      label: 'Category',

      render: (_, row) => (
        <span className="inline-flex px-2.5 py-1 rounded-full bg-blue-50 text-blue-900 text-xs font-semibold">
          {getCategoryName(row)}
        </span>
      ),
    },

    {
      key: 'level',
      label: 'Level',

      render: (val) => (
        <span className="text-sm text-blue-500">
          {val || '-'}
        </span>
      ),
    },

    {
      key: 'price',
      label: 'Price',

      render: (val) => (
        <span className="text-sm font-semibold text-blue-900">
          {val !== null &&
          val !== undefined &&
          val !== ''
            ? `$${val}`
            : 'Free'}
        </span>
      ),
    },

    {
      key: 'is_active',
      label: 'Status',

      render: (val) => (
        <span
          className={`inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[11px] font-semibold ${
            val
              ? 'bg-blue-50 text-blue-700'
              : 'bg-red-50 text-red-600'
          }`}
        >
          <span
            className={`w-1.5 h-1.5 rounded-full ${
              val ? 'bg-blue-500' : 'bg-red-500'
            }`}
          />

          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },

    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => handleEditCourse(row)}
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-blue-50 text-blue-900 hover:bg-blue-900 hover:text-white transition"
            title="Edit Course"
          >
            <FiEdit2 size={14} />
          </button>

          <button
            type="button"
            onClick={() =>
              handleDeleteCourse(row.id)
            }
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-red-50 text-red-600 hover:bg-red-600 hover:text-white transition"
            title="Delete Course"
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  // =====================================================
  // CATEGORY COLUMNS
  // =====================================================
  const categoryColumns = [
    {
      key: 'name',
      label: 'Category',

      render: (val, row) => (
        <div>
          <p className="text-sm font-bold text-blue-900">
            {val || 'Untitled'}
          </p>

          {row.description && (
            <p className="text-xs text-blue-400 mt-1 max-w-[280px] truncate">
              {row.description}
            </p>
          )}
        </div>
      ),
    },

    {
      key: 'slug',
      label: 'Slug',

      render: (val) => (
        <span className="text-xs font-mono bg-blue-50 text-blue-500 px-2 py-1 rounded">
          {val || '-'}
        </span>
      ),
    },

    {
      key: 'order',
      label: 'Order',

      render: (val) => (
        <span className="inline-flex items-center justify-center min-w-[34px] h-8 px-2 bg-blue-50 text-blue-900 rounded-lg text-xs font-bold">
          {val ?? 0}
        </span>
      ),
    },

    {
      key: 'is_active',
      label: 'Status',

      render: (val) => (
        <span
          className={`inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[11px] font-semibold ${
            val
              ? 'bg-blue-50 text-blue-700'
              : 'bg-red-50 text-red-600'
          }`}
        >
          <span
            className={`w-1.5 h-1.5 rounded-full ${
              val ? 'bg-blue-500' : 'bg-red-500'
            }`}
          />

          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },

    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() =>
              handleEditCategory(row)
            }
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-blue-50 text-blue-900 hover:bg-blue-900 hover:text-white transition"
            title="Edit Category"
          >
            <FiEdit2 size={14} />
          </button>

          <button
            type="button"
            onClick={() =>
              handleDeleteCategory(row.id)
            }
            className="w-8 h-8 flex items-center justify-center rounded-lg bg-red-50 text-red-600 hover:bg-red-600 hover:text-white transition"
            title="Delete Category"
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  // =====================================================
  // UI
  // =====================================================
  return (
    <div className="space-y-6">
      {/* =================================================
          PAGE HEADER
      ================================================= */}
      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-1xl font-bold text-blue-900">
            Courses Management
          </h1>

          <p className="text-sm text-blue-400 mt-1">
            Manage courses and course categories
          </p>
        </div>

        <button
          type="button"
          onClick={
            activeTab === 'courses'
              ? handleAddCourse
              : handleAddCategory
          }
          className="inline-flex items-center justify-center gap-2 h-10 px-4 bg-red-600 text-white rounded-lg text-sm font-semibold shadow-sm hover:bg-red-700 hover:shadow-md transition-all"
        >
          <FiPlus />

          <span>
            {activeTab === 'courses'
              ? 'Add Course'
              : 'Add Category'}
          </span>
        </button>
      </div>

      {/* =================================================
          STATS
      ================================================= */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <AdminCard className="p-5">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-blue-50 text-blue-900 flex items-center justify-center">
              <FiBookOpen size={22} />
            </div>

            <div>
              <p className="text-sm text-blue-400">
                Total Courses
              </p>

              <p className="text-2xl font-bold text-blue-900">
                {courses.length}
              </p>
            </div>
          </div>
        </AdminCard>

        <AdminCard className="p-5">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-blue-50 text-blue-900 flex items-center justify-center">
              <FiLayers size={22} />
            </div>

            <div>
              <p className="text-sm text-blue-400">
                Categories
              </p>

              <p className="text-2xl font-bold text-blue-900">
                {categories.length}
              </p>
            </div>
          </div>
        </AdminCard>
      </div>

      {/* =================================================
          TABS
      ================================================= */}
      <div className="bg-white border border-blue-200 rounded-2xl shadow-sm p-1.5 inline-flex">
        <button
          type="button"
          onClick={() => setActiveTab('courses')}
          className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold transition ${
            activeTab === 'courses'
              ? 'bg-blue-900 text-white shadow-sm'
              : 'text-blue-400 hover:bg-blue-50'
          }`}
        >
          <FiBookOpen />

          Courses

          <span
            className={`text-[10px] px-2 py-0.5 rounded-full ${
              activeTab === 'courses'
                ? 'bg-white/20 text-white'
                : 'bg-blue-50 text-blue-400'
            }`}
          >
            {courses.length}
          </span>
        </button>

        <button
          type="button"
          onClick={() => setActiveTab('categories')}
          className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold transition ${
            activeTab === 'categories'
              ? 'bg-blue-900 text-white shadow-sm'
              : 'text-blue-400 hover:bg-blue-50'
          }`}
        >
          <FiLayers />

          Categories

          <span
            className={`text-[10px] px-2 py-0.5 rounded-full ${
              activeTab === 'categories'
                ? 'bg-white/20 text-white'
                : 'bg-blue-50 text-blue-400'
            }`}
          >
            {categories.length}
          </span>
        </button>
      </div>

      {/* =================================================
          TABLE
      ================================================= */}
      <AdminCard className="overflow-hidden border-blue-200">
        {activeTab === 'courses' ? (
          <AdminTable
            columns={courseColumns}
            data={courses}
            loading={loading}
          />
        ) : (
          <AdminTable
            columns={categoryColumns}
            data={categories}
            loading={loading}
          />
        )}
      </AdminCard>

      {/* =================================================
          COURSE MODAL
      ================================================= */}
      <AdminModal
        isOpen={courseModalOpen}
        onClose={closeCourseModal}
        title={
          editingCourse
            ? 'Edit Course'
            : 'Create Course'
        }
      >
        <form onSubmit={handleCourseSubmit}>
          <div className="space-y-5">
            {/* Title */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Course Title *
              </label>

              <input
                type="text"
                value={courseFormData.title}
                onChange={(e) => {
                  const title = e.target.value;

                  setCourseFormData({
                    ...courseFormData,
                    title,
                    slug: editingCourse
                      ? courseFormData.slug
                      : createSlug(title),
                  });
                }}
                className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                placeholder="Example: Web Development"
                required
              />
            </div>

            {/* Slug */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Slug *
              </label>

              <input
                type="text"
                value={courseFormData.slug}
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    slug: createSlug(
                      e.target.value
                    ),
                  })
                }
                className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                placeholder="web-development"
                required
              />
            </div>

            {/* Category */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Category
              </label>

              <select
                value={
                  courseFormData.category_id
                }
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    category_id:
                      e.target.value,
                  })
                }
                className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition bg-white"
              >
                <option value="">
                  Select Category
                </option>

                {categories
                  .filter(
                    (category) =>
                      category.is_active !== false
                  )
                  .map((category) => (
                    <option
                      key={category.id}
                      value={category.id}
                    >
                      {category.name}
                    </option>
                  ))}
              </select>
            </div>

            {/* Description */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Description
              </label>

              <textarea
                value={
                  courseFormData.description
                }
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    description:
                      e.target.value,
                  })
                }
                className="w-full px-3.5 py-3 border border-blue-200 rounded-lg text-sm text-blue-900 resize-none outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                rows="4"
                placeholder="Course description..."
              />
            </div>

            {/* Duration + Level */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  Duration
                </label>

                <input
                  type="text"
                  value={
                    courseFormData.duration
                  }
                  onChange={(e) =>
                    setCourseFormData({
                      ...courseFormData,
                      duration:
                        e.target.value,
                    })
                  }
                  className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                  placeholder="3 Months"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  Level
                </label>

                <select
                  value={
                    courseFormData.level
                  }
                  onChange={(e) =>
                    setCourseFormData({
                      ...courseFormData,
                      level:
                        e.target.value,
                    })
                  }
                  className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition bg-white"
                >
                  <option value="">
                    Select Level
                  </option>

                  <option value="Beginner">
                    Beginner
                  </option>

                  <option value="Intermediate">
                    Intermediate
                  </option>

                  <option value="Advanced">
                    Advanced
                  </option>

                  <option value="All Levels">
                    All Levels
                  </option>
                </select>
              </div>
            </div>

            {/* Price + Order */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  Price
                </label>

                <input
                  type="text"
                  value={
                    courseFormData.price
                  }
                  onChange={(e) =>
                    setCourseFormData({
                      ...courseFormData,
                      price: e.target.value,
                    })
                  }
                  className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                  placeholder="Example: Free, $50, or Contact us"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  Display Order
                </label>

                <input
                  type="number"
                  min="0"
                  value={
                    courseFormData.order
                  }
                  onChange={(e) =>
                    setCourseFormData({
                      ...courseFormData,
                      order:
                        parseInt(
                          e.target.value,
                          10
                        ) || 0,
                    })
                  }
                  className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                />
              </div>
            </div>

            {/* Course Image Upload */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                {editingCourse
                  ? 'Course Image'
                  : 'Upload Course Image'}
              </label>

              {!courseImagePreview ? (
                <label className="mt-2 border-2 border-dashed border-blue-200 rounded-xl p-6 flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition">
                  <FiUploadCloud
                    size={30}
                    className="text-blue-900 mb-2"
                  />

                  <p className="text-sm font-semibold text-blue-900">
                    Click to upload image
                  </p>

                  <p className="text-xs text-blue-300 mt-1">
                    PNG, JPG, JPEG, WEBP up to
                    5MB
                  </p>

                  <input
                    ref={courseFileRef}
                    type="file"
                    accept="image/png,image/jpeg,image/jpg,image/webp"
                    onChange={
                      handleCourseImageChange
                    }
                    className="hidden"
                  />
                </label>
              ) : (
                <div className="relative mt-2 rounded-xl overflow-hidden border border-blue-200">
                  <img
                    src={courseImagePreview}
                    alt="Course Preview"
                    className="w-full h-52 object-cover"
                  />

                  <button
                    type="button"
                    onClick={
                      removeCourseImage
                    }
                    className="absolute top-3 right-3 w-9 h-9 rounded-full bg-black/70 text-white flex items-center justify-center hover:bg-red-600 transition"
                  >
                    <FiX />
                  </button>

                  <label className="absolute bottom-3 right-3 bg-white text-blue-900 px-4 py-2 rounded-lg text-xs font-semibold shadow cursor-pointer hover:bg-blue-900 hover:text-white transition">
                    Change Image

                    <input
                      ref={courseFileRef}
                      type="file"
                      accept="image/png,image/jpeg,image/jpg,image/webp"
                      onChange={
                        handleCourseImageChange
                      }
                      className="hidden"
                    />
                  </label>
                </div>
              )}
            </div>

            {/* Active */}
            <label
              className={`flex items-center justify-between p-4 border rounded-xl cursor-pointer transition ${
                courseFormData.is_active
                  ? 'bg-blue-50 border-blue-200'
                  : 'bg-white border-blue-200'
              }`}
            >
              <div className="flex items-center gap-3">
                <div
                  className={`w-9 h-9 rounded-lg flex items-center justify-center ${
                    courseFormData.is_active
                      ? 'bg-blue-100 text-blue-600'
                      : 'bg-blue-50 text-blue-300'
                  }`}
                >
                  {courseFormData.is_active ? (
                    <FiCheckCircle />
                  ) : (
                    <FiXCircle />
                  )}
                </div>

                <div>
                  <p className="text-sm font-semibold text-blue-900">
                    Active Course
                  </p>

                  <p className="text-xs text-blue-300">
                    Show this course on the
                    website
                  </p>
                </div>
              </div>

              <input
                type="checkbox"
                checked={
                  courseFormData.is_active
                }
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    is_active:
                      e.target.checked,
                  })
                }
                className="w-4 h-4 accent-blue-600"
              />
            </label>

            {/* Featured - Changed Yellow to Red */}
            <label className="flex items-center gap-3 p-4 border border-blue-200 rounded-xl cursor-pointer hover:bg-blue-50 transition">
              <input
                type="checkbox"
                checked={
                  courseFormData.is_featured
                }
                onChange={(e) =>
                  setCourseFormData({
                    ...courseFormData,
                    is_featured:
                      e.target.checked,
                  })
                }
                className="w-4 h-4 accent-red-500"
              />

              <div>
                <p className="text-sm font-semibold text-blue-900">
                  Featured Course
                </p>

                <p className="text-xs text-blue-300">
                  Display this course in
                  featured sections
                </p>
              </div>
            </label>
          </div>

          {/* Buttons */}
          <div className="mt-6 pt-4 border-t border-blue-200 flex justify-end gap-3">
            <button
              type="button"
              onClick={closeCourseModal}
              disabled={courseSubmitting}
              className="h-10 px-4 bg-white border border-blue-200 text-blue-400 rounded-lg text-sm font-semibold hover:bg-blue-50 transition disabled:opacity-50"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={courseSubmitting}
              className="min-w-[110px] h-10 px-5 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {courseSubmitting
                ? editingCourse
                  ? 'Updating...'
                  : 'Creating...'
                : editingCourse
                ? 'Update Course'
                : 'Create Course'}
            </button>
          </div>
        </form>
      </AdminModal>

      {/* =================================================
          CATEGORY MODAL
      ================================================= */}
      <AdminModal
        isOpen={categoryModalOpen}
        onClose={closeCategoryModal}
        title={
          editingCategory
            ? 'Edit Category'
            : 'Create Category'
        }
      >
        <form onSubmit={handleCategorySubmit}>
          <div className="space-y-5">
            {/* Name */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Category Name *
              </label>

              <input
                type="text"
                value={
                  categoryFormData.name
                }
                onChange={(e) => {
                  const name = e.target.value;

                  setCategoryFormData({
                    ...categoryFormData,
                    name,
                    slug: editingCategory
                      ? categoryFormData.slug
                      : createSlug(name),
                  });
                }}
                className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                placeholder="Example: IT Courses"
                required
              />
            </div>

            {/* Slug */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Slug *
              </label>

              <input
                type="text"
                value={
                  categoryFormData.slug
                }
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    slug: createSlug(
                      e.target.value
                    ),
                  })
                }
                className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                placeholder="it-courses"
                required
              />

              <p className="text-[11px] text-blue-300 mt-1">
                Used in URLs and internal
                references
              </p>
            </div>

            {/* Description */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Description
              </label>

              <textarea
                value={
                  categoryFormData.description
                }
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    description:
                      e.target.value,
                  })
                }
                className="w-full px-3.5 py-3 border border-blue-200 rounded-lg text-sm text-blue-900 resize-none outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
                rows="4"
                placeholder="Category description..."
              />
            </div>

            {/* Order */}
            <div>
              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Display Order
              </label>

              <input
                type="number"
                min="0"
                value={
                  categoryFormData.order
                }
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    order:
                      parseInt(
                        e.target.value,
                        10
                      ) || 0,
                  })
                }
                className="w-full h-11 px-3.5 border border-blue-200 rounded-lg text-sm text-blue-900 outline-none focus:border-blue-900 focus:ring-2 focus:ring-blue-900/10 transition"
              />

              <p className="text-[11px] text-blue-300 mt-1">
                Lower number appears first
              </p>
            </div>

            {/* Active */}
            <label
              className={`flex items-center justify-between p-4 border rounded-xl cursor-pointer transition ${
                categoryFormData.is_active
                  ? 'bg-blue-50 border-blue-200'
                  : 'bg-white border-blue-200'
              }`}
            >
              <div className="flex items-center gap-3">
                <div
                  className={`w-9 h-9 rounded-lg flex items-center justify-center ${
                    categoryFormData.is_active
                      ? 'bg-blue-100 text-blue-600'
                      : 'bg-blue-50 text-blue-300'
                  }`}
                >
                  {categoryFormData.is_active ? (
                    <FiCheckCircle />
                  ) : (
                    <FiXCircle />
                  )}
                </div>

                <div>
                  <p className="text-sm font-semibold text-blue-900">
                    Active Category
                  </p>

                  <p className="text-xs text-blue-300">
                    Show this category on the
                    website
                  </p>
                </div>
              </div>

              <input
                type="checkbox"
                checked={
                  categoryFormData.is_active
                }
                onChange={(e) =>
                  setCategoryFormData({
                    ...categoryFormData,
                    is_active:
                      e.target.checked,
                  })
                }
                className="w-4 h-4 accent-blue-600"
              />
            </label>
          </div>

          {/* Buttons */}
          <div className="mt-6 pt-4 border-t border-blue-200 flex justify-end gap-3">
            <button
              type="button"
              onClick={closeCategoryModal}
              disabled={categorySubmitting}
              className="h-10 px-4 bg-white border border-blue-200 text-blue-400 rounded-lg text-sm font-semibold hover:bg-blue-50 transition disabled:opacity-50"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={categorySubmitting}
              className="min-w-[110px] h-10 px-5 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700 transition disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {categorySubmitting
                ? editingCategory
                  ? 'Updating...'
                  : 'Creating...'
                : editingCategory
                ? 'Update Category'
                : 'Create Category'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminCourses;
